// HasImagesWith applies the HasEdge predicate on the "images" edge with a given conditions (other predicates).
func HasImagesWith(preds ...predicate.ActorImage) predicate.ActorProfile {
	return predicate.ActorProfile(func(s *sql.Selector) {
		step := newImagesStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ActorProfile) predicate.ActorProfile {
	return predicate.ActorProfile(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ActorProfile) predicate.ActorProfile {
	return predicate.ActorProfile(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ActorProfile) predicate.ActorProfile {
	return predicate.ActorProfile(sql.NotPredicates(p))
}
